import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
  LayoutDashboard,
  Package,
  Star,
  Award,
  TrendingUp,
  Users,
  DollarSign,
  Activity,
  Eye,
  CalendarClock,
  LineChart,
  ExternalLink,
  BarChart3,
  Info,
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { useI18n } from '@/i18n/I18nContext';
import { getI18nValue } from '@/lib/i18n-text';
import { useProducts } from '@/hooks/useProducts';
import { useAdvantages } from '@/hooks/useAdvantages';
import { useTestimonials } from '@/hooks/useTestimonials';
import { useInquiries } from '@/hooks/useInquiries';
import { useAnalytics, type AnalyticsStats } from '@/hooks/useAnalytics';
import { useAnalyticsSettings } from '@/hooks/useAnalyticsSettings';
import { Image } from '@/components/ui/image';
import ReactECharts from 'echarts-for-react';
import { CHART_COLORS } from '@/lib/chart-colors';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { Link } from 'react-router-dom';
import { format } from 'date-fns';

export default function AdminDashboardPage() {
  const { adminT, adminLanguage } = useI18n();
  const { products } = useProducts();
  const { advantages } = useAdvantages();
  const { testimonials } = useTestimonials();
  const { totalCount: inquiryTotal, unreadCount } = useInquiries();
  const { stats: analyticsStats } = useAnalytics();
  const { settings: analyticsSettings } = useAnalyticsSettings();

  const monthKeys = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul'] as const;
  const monthLabels = monthKeys.map((k) => adminT(`admin.months.${k}`));

  const kpis = [
    { label: adminT('admin.totalProducts'), value: products.length, icon: Package, change: adminT('admin.kpiNewThisMonth'), color: 'text-primary' },
    { label: adminT('admin.totalAdvantages'), value: advantages.length, icon: Award, change: adminT('admin.kpiCoreAdvantages'), color: 'text-chart-2' },
    { label: adminT('admin.totalTestimonials'), value: testimonials.length, icon: Star, change: adminT('admin.kpiCustomerReviews'), color: 'text-chart-3' },
    { label: adminT('admin.inquiries'), value: inquiryTotal, icon: Activity, change: unreadCount > 0 ? adminT('admin.kpiUnread').replace('{count}', String(unreadCount)) : adminT('admin.kpiGrowthMonth'), color: 'text-chart-4' },
  ];

  // Inquiries chart data
  const inquiriesOption = {
    color: CHART_COLORS,
    tooltip: { trigger: 'axis' as const },
    grid: { left: '3%', right: '4%', bottom: '3%', containLabel: true },
    xAxis: {
      type: 'category',
      boundaryGap: false,
      data: monthLabels,
      axisLine: { lineStyle: { color: 'hsl(var(--border))' } },
      axisLabel: { color: 'hsl(var(--muted-foreground))', fontSize: 11 },
    },
    yAxis: {
      type: 'value',
      axisLine: { show: false },
      splitLine: { lineStyle: { color: 'hsl(var(--border))', opacity: 0.4 } },
      axisLabel: { color: 'hsl(var(--muted-foreground))', fontSize: 11 },
    },
    series: [
      {
        name: 'Inquiries',
        type: 'line',
        smooth: true,
        areaStyle: {
          color: {
            type: 'linear',
            x: 0, y: 0, x2: 0, y2: 1,
            colorStops: [
              { offset: 0, color: 'rgba(230, 57, 70, 0.3)' },
              { offset: 1, color: 'rgba(230, 57, 70, 0.02)' },
            ],
          },
        },
        lineStyle: { color: CHART_COLORS[0], width: 2 },
        itemStyle: { color: CHART_COLORS[0] },
        data: [28, 35, 42, 38, 56, 62, 127],
      },
    ],
  };

  // Category distribution
  const categoryData: Record<string, number> = {};
  products.forEach((p) => {
    categoryData[p.category] = (categoryData[p.category] || 0) + 1;
  });
  const categoryOption = {
    color: CHART_COLORS,
    tooltip: { trigger: 'item' as const },
    legend: {
      orient: 'vertical' as const,
      right: 0,
      top: 'center',
      textStyle: { color: 'hsl(var(--muted-foreground))', fontSize: 11 },
    },
    series: [
      {
        type: 'pie',
        radius: ['55%', '75%'],
        center: ['35%', '50%'],
        avoidLabelOverlap: false,
        itemStyle: { borderRadius: 4, borderColor: 'hsl(var(--card))', borderWidth: 2 },
        label: { show: false },
        data: Object.entries(categoryData).map(([name, value]) => ({ name, value })),
      },
    ],
  };

  return (
    <div className="space-y-6">
      <PageBreadcrumb items={[]} firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }} />
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-foreground">{adminT('admin.dashboard')}</h1>
          <p className="text-sm text-muted-foreground mt-1">
            {adminT('admin.welcomeBack')}
          </p>
        </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {kpis.map((kpi, idx) => {
          const Icon = kpi.icon;
          return (
            <motion.div
              key={kpi.label}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.4, delay: idx * 0.05 }}
            >
              <Card className="border-border/40 bg-card">
                <CardContent className="p-5">
                  <div className="flex items-center justify-between mb-3">
                    <div className={`w-10 h-10 rounded-lg bg-${idx % 4 === 0 ? 'primary' : `chart-${idx + 1}`}/10 flex items-center justify-center`}>
                      <Icon className={`size-5 ${kpi.color}`} />
                    </div>
                    <TrendingUp className="size-4 text-success" />
                  </div>
                  <div className="text-2xl font-bold text-foreground mb-1">{kpi.value}</div>
                  <div className="text-xs text-muted-foreground">{kpi.label}</div>
                  <div className="text-[10px] text-success mt-2">{kpi.change}</div>
                </CardContent>
              </Card>
            </motion.div>
          );
        })}
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <Card className="lg:col-span-2 border-border/40 bg-card">
          <CardHeader className="pb-2">
            <CardTitle className="text-base">{adminT('admin.inquiryTrend')}</CardTitle>
          </CardHeader>
          <CardContent>
            <ReactECharts
              option={inquiriesOption}
              style={{ height: '300px' }}
              opts={{ renderer: 'svg' }}
            />
          </CardContent>
        </Card>

        <Card className="border-border/40 bg-card">
          <CardHeader className="pb-2">
            <CardTitle className="text-base">{adminT('admin.productCategories')}</CardTitle>
          </CardHeader>
          <CardContent>
            <ReactECharts
              option={categoryOption}
              style={{ height: '300px' }}
              opts={{ renderer: 'svg' }}
            />
          </CardContent>
        </Card>
      </div>

      {/* Recent activity */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Card className="border-border/40 bg-card">
          <CardHeader>
            <CardTitle className="text-base">{adminT('admin.recentProducts')}</CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            <div className="divide-y divide-border/40">
              {products.slice(0, 4).map((product) => (
                <div key={product.id} className="flex items-center gap-3 p-4">
                  <div className="relative w-12 h-12 rounded-md overflow-hidden bg-muted shrink-0">
                    <Image src={product.image} alt={getI18nValue(product.name, adminLanguage)} className="absolute inset-0 w-full h-full object-contain" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <h4 className="text-sm font-medium text-foreground truncate">{getI18nValue(product.name, adminLanguage)}</h4>
                    <p className="text-xs text-muted-foreground">{product.category}</p>
                  </div>
                  <Badge variant="outline" className="shrink-0 text-[10px]">
                    {(product.customFields || []).find((f) => f.key.en.toLowerCase() === 'power')?.value.en || product.category}
                  </Badge>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        <Card className="border-border/40 bg-card">
          <CardHeader>
            <CardTitle className="text-base">{adminT('admin.recentTestimonials')}</CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            <div className="divide-y divide-border/40">
              {testimonials.slice(0, 4).map((t) => (
                <div key={t.id} className="p-4">
                  <div className="flex items-center gap-2 mb-2">
                    <div className="w-7 h-7 rounded-full bg-primary/10 flex items-center justify-center">
                      <span className="text-xs font-bold text-primary">
                        {t.customerName.en.charAt(0)}
                      </span>
                    </div>
                    <div className="min-w-0">
                      <h4 className="text-sm font-medium text-foreground truncate">{t.customerName.en}</h4>
                      <p className="text-[10px] text-muted-foreground">{t.company}</p>
                    </div>
                  </div>
                   <p className="text-xs text-muted-foreground line-clamp-2">{getI18nValue(t.content, adminLanguage)}</p>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Website Traffic Section */}
      <TrafficSection
        stats={analyticsStats}
        settings={analyticsSettings}
        inquiryTotal={inquiryTotal}
        adminT={adminT}
        adminLanguage={adminLanguage}
      />
    </div>
  );
}

function TrafficSection({
  stats,
  settings,
  inquiryTotal,
  adminT,
  adminLanguage,
}: {
  stats: AnalyticsStats;
  settings: { gaEnabled: boolean; gaMeasurementId: string; clarityEnabled: boolean; clarityProjectId: string };
  inquiryTotal: number;
  adminT: (k: string) => string;
  adminLanguage: string;
}) {
  const kpis = [
    {
      label: adminT('admin.totalPV'),
      value: stats.totalPV.toLocaleString(),
      icon: Eye,
      sub: adminT('admin.localStatsMode'),
      color: 'text-primary',
      bg: 'bg-primary/10',
    },
    {
      label: adminT('admin.todayPV'),
      value: stats.todayPV.toLocaleString(),
      icon: CalendarClock,
      sub: adminT('admin.singleVisitorNote'),
      color: 'text-chart-2',
      bg: 'bg-chart-2/10',
    },
    {
      label: adminT('admin.uniqueVisitors'),
      value: '1',
      icon: Users,
      sub: adminT('admin.localStatsMode'),
      color: 'text-chart-3',
      bg: 'bg-chart-3/10',
    },
    {
      label: adminT('admin.lastVisit'),
      value: stats.lastVisitTime ? format(stats.lastVisitTime, 'MM-dd HH:mm') : '—',
      icon: Activity,
      sub: stats.lastVisitPage || '—',
      color: 'text-chart-4',
      bg: 'bg-chart-4/10',
    },
  ];

  const maxDaily = Math.max(1, ...stats.dailyTrend.map((d) => d.count));
  const maxTopPage = Math.max(1, ...stats.topPages.map((p) => p.count));

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-semibold text-foreground flex items-center gap-2">
          <BarChart3 className="size-5 text-primary" />
          {adminT('admin.analyticsLocalStats')}
        </h2>
        <Link to="/admin/analytics">
          <Button variant="outline" size="sm">
            <ExternalLink className="size-3.5 mr-2" />
            {adminT('admin.analyticsSettings')}
          </Button>
        </Link>
      </div>

      <Alert className="bg-primary/5 border-primary/20">
        <Info className="h-4 w-4 text-primary" />
        <AlertTitle className="text-foreground font-medium text-sm">
          {adminT('admin.localStatsMode')}
        </AlertTitle>
        <AlertDescription className="text-muted-foreground text-xs">
          {adminT('admin.analyticsLocalNote')}
        </AlertDescription>
      </Alert>

      {/* Traffic KPIs */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {kpis.map((kpi, idx) => {
          const Icon = kpi.icon;
          return (
            <Card key={kpi.label} className="border-border/40 bg-card">
              <CardContent className="p-4">
                <div className="flex items-center justify-between mb-2">
                  <div className={`w-8 h-8 rounded-md ${kpi.bg} flex items-center justify-center`}>
                    <Icon className={`size-4 ${kpi.color}`} />
                  </div>
                </div>
                <div className="text-xl font-bold text-foreground mb-0.5 tabular-nums">{kpi.value}</div>
                <div className="text-[11px] text-muted-foreground">{kpi.label}</div>
                <div className="text-[10px] text-muted-foreground/70 mt-1 line-clamp-1">{kpi.sub}</div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {/* Chart + Top Pages + Quick Links */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        {/* 7-day trend */}
        <Card className="lg:col-span-2 border-border/40 bg-card">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm flex items-center gap-2">
              <LineChart className="size-4 text-primary" />
              {adminT('admin.trafficTrend')} — {adminT('admin.last7Days')}
            </CardTitle>
          </CardHeader>
          <CardContent>
            {stats.dailyTrend.every((d) => d.count === 0) ? (
              <div className="py-10 text-center">
                <BarChart3 className="size-6 text-muted-foreground/30 mx-auto mb-2" />
                <p className="text-xs text-muted-foreground">{adminT('admin.noData')}</p>
              </div>
            ) : (
              <div className="flex items-end gap-2 h-36 pt-3">
                {stats.dailyTrend.map((d) => {
                  const heightPct = (d.count / maxDaily) * 100;
                  const dateLabel = d.date.slice(5);
                  return (
                    <div key={d.date} className="flex-1 flex flex-col items-center gap-1.5">
                      <div className="text-[10px] font-medium tabular-nums text-foreground/70">{d.count || 0}</div>
                      <div className="w-full flex-1 flex items-end">
                        <div
                          className="w-full bg-primary/70 rounded-t-sm transition-all"
                          style={{ height: `${heightPct}%`, minHeight: d.count > 0 ? '3px' : '2px', opacity: d.count > 0 ? 1 : 0.2 }}
                        />
                      </div>
                      <div className="text-[9px] text-muted-foreground tabular-nums">{dateLabel}</div>
                    </div>
                  );
                })}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Top Pages + External Links */}
        <div className="space-y-4">
          <Card className="border-border/40 bg-card">
            <CardHeader className="pb-2">
              <CardTitle className="text-sm flex items-center gap-2">
                <TrendingUp className="size-4 text-primary" />
                {adminT('admin.topPages')}
              </CardTitle>
            </CardHeader>
            <CardContent className="p-0">
              {stats.topPages.length === 0 ? (
                <div className="py-8 text-center">
                  <p className="text-xs text-muted-foreground">{adminT('admin.noData')}</p>
                </div>
              ) : (
                <div className="divide-y divide-border/40">
                  {stats.topPages.slice(0, 5).map((p, i) => (
                    <div key={p.path} className="px-3 py-2.5">
                      <div className="flex items-center justify-between mb-1">
                        <div className="flex items-center gap-2 min-w-0">
                          <span className="shrink-0 w-4 h-4 rounded-full bg-primary/10 text-primary text-[9px] font-bold flex items-center justify-center">
                            {i + 1}
                          </span>
                          <span className="text-xs font-medium text-foreground truncate">{p.path}</span>
                        </div>
                        <span className="shrink-0 text-xs tabular-nums text-foreground/70">{p.count}</span>
                      </div>
                      <div className="w-full h-1 bg-muted/30 rounded-full overflow-hidden">
                        <div className="h-full bg-primary/60 rounded-full" style={{ width: `${(p.count / maxTopPage) * 100}%` }} />
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>

          {/* Quick links to GA / Clarity */}
          <Card className="border-border/40 bg-card">
            <CardHeader className="pb-2">
              <CardTitle className="text-sm">{adminT('admin.analyticsSettings')}</CardTitle>
            </CardHeader>
            <CardContent className="space-y-2">
              <Button
                variant="outline"
                size="sm"
                className="w-full justify-start gap-2"
                onClick={() => window.open('https://analytics.google.com/', '_blank', 'noopener,noreferrer')}
                disabled={!settings.gaEnabled || !settings.gaMeasurementId}
              >
                <BarChart3 className="size-3.5" />
                {adminT('admin.viewGaReport')}
                <ExternalLink className="size-3 ml-auto opacity-60" />
              </Button>
              <Button
                variant="outline"
                size="sm"
                className="w-full justify-start gap-2"
                onClick={() => window.open('https://clarity.microsoft.com/', '_blank', 'noopener,noreferrer')}
                disabled={!settings.clarityEnabled || !settings.clarityProjectId}
              >
                <Activity className="size-3.5" />
                {adminT('admin.viewClarityReport')}
                <ExternalLink className="size-3 ml-auto opacity-60" />
              </Button>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}
